#!/bin/bash
# Print the three most frequent IP addresses from access.log, one per line,
# most frequent first; ties broken by first appearance in the log.
awk '{
    ip = $1
    if (!(ip in count)) {
        order[++n] = ip
    }
    count[ip]++
}
END {
    for (i = 1; i <= 3; i++) {
        best = 0
        best_pos = 0
        for (j = 1; j <= n; j++) {
            if (picked[j]) continue
            if (best == 0 || count[order[j]] > count[order[best]]) {
                best = j
            }
        }
        picked[best] = 1
        print order[best]
    }
}' access.log
